"""Return files generated by code interpreter inline.

The hosted agent server drops file annotations, so the chat app only sees a dead
`sandbox:/mnt/data/...` link. This middleware downloads each generated file from the
code interpreter container and appends it to the reply as markdown with a data URI
(an image for images, a download link for everything else).
"""

from __future__ import annotations

import base64
import mimetypes
import re
from typing import Any

from agent_framework import AgentContext, AgentMiddleware, Content

MAX_BYTES = 5 * 1024 * 1024
_SAFE_NAME = re.compile(r"[^A-Za-z0-9._ -]")


def _citations(content: Any) -> list[tuple[str, str, str]]:
    found = []
    raw = getattr(getattr(content, "raw_representation", None), "annotation", None)
    if getattr(content, "type", None) == "hosted_file" and getattr(raw, "container_id", None):
        found.append((raw.container_id, raw.file_id, getattr(raw, "filename", None) or raw.file_id))
    for ann in getattr(content, "annotations", None) or []:
        props = ann.get("additional_properties") or {}
        container_id, file_id = props.get("container_id"), ann.get("file_id")
        if container_id and file_id:
            found.append((container_id, file_id, ann.get("url") or file_id))
    return found


async def _markdown(openai_client: Any, container_id: str, file_id: str, filename: str) -> str:
    name = _SAFE_NAME.sub("_", filename.rsplit("/", 1)[-1]) or file_id
    try:
        response = await openai_client.containers.files.content.retrieve(file_id, container_id=container_id)
        data = await response.aread()
    except Exception as exc:  # keep the reply usable if the download fails
        return f"\n\n(Could not retrieve generated file {name}: {type(exc).__name__})"
    if len(data) > MAX_BYTES:
        return f"\n\n(Generated file {name} is too large to return inline.)"
    mime = mimetypes.guess_type(name)[0] or "application/octet-stream"
    uri = f"data:{mime};base64,{base64.b64encode(data).decode()}"
    if mime.startswith("image/"):
        return f"\n\n![{name}]({uri})"
    return f"\n\n[Download {name}]({uri})"


class GeneratedFilesMiddleware(AgentMiddleware):
    def __init__(self, client: Any):
        self._client = client

    async def _render(self, contents: list[Any], seen: set[str]) -> str:
        out = ""
        for content in contents:
            for container_id, file_id, filename in _citations(content):
                if file_id in seen:
                    continue
                seen.add(file_id)
                out += await _markdown(self._client.client, container_id, file_id, filename)
        return out

    async def process(self, context: AgentContext, call_next) -> None:
        await call_next()
        result, seen = context.result, set()
        if result is None:
            return
        if context.stream:

            async def hook(update):
                extra = await self._render(update.contents, seen)
                if extra:
                    update.contents.append(Content.from_text(extra))
                return update

            result.with_transform_hook(hook)
            return
        for message in result.messages:
            extra = await self._render(message.contents, seen)
            if extra:
                message.contents.append(Content.from_text(extra))
